{{-- A ranked list with bars. rows: [['label', 'value', 'share' => 0 to 100, or null for no bar, 'href', 'class' => bar class, 'quality' => 'q2', 'icon' => image address]]. A row without an icon shows a placeholder square while another row has one. --}}
@props(['rows', 'plain' => false])
@php($icons = array_filter(array_column($rows, 'icon')) !== [])
<ol @class(['rank', 'plain' => $plain])>@foreach ($rows as $row)<li>@if (! empty($row['href']))<a @class(['who', $row['quality'] ?? null]) href="{{ $row['href'] }}"><x-item-icon :icon="$row['icon'] ?? null" :any="$icons" />{{ $row['label'] }}</a>@else<span class="who"><x-item-icon :icon="$row['icon'] ?? null" :any="$icons" />{{ $row['label'] }}</span>@endif<span class="val">{{ $row['value'] }}</span>@if ($row['share'] !== null)<span class="track"><i @class([$row['class'] ?? null]) style="width:{{ round($row['share'], 1) }}%"></i></span>@endif</li>@endforeach</ol>
